using System.Security.Cryptography;
using System.Text.Json;
using UnscRelay.Core;
internal static class LocalAccountErasureChecks
{
 public static async Task<int> Run(){var root=Directory.CreateTempSubdirectory("relay-erasure-engine-");var count=0;void Check(bool value,string label){if(!value)throw new Exception(label);count++;Console.WriteLine("PASS local erasure engine: "+label);}try{using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);var publicKey=key.ExportSubjectPublicKeyInfo();var kid=Convert.ToHexString(SHA256.HashData(publicKey))[..32];var verifier=new ErasureReceiptVerifier(new Dictionary<string,string>{{kid,Convert.ToBase64String(publicKey)}});var now=DateTimeOffset.UtcNow;var owner=new string('A',64);const string subject="61616161-6161-4161-8161-616161616161";var claims=new ErasureReceiptClaims(1,"https://unsc.responda.eu","unsc-relay-desktop-erasure",owner,subject,Guid.NewGuid(),now.AddDays(-31).ToUnixTimeMilliseconds(),now.AddDays(-1).ToUnixTimeMilliseconds(),"completed",now.ToUnixTimeMilliseconds());string Encode(byte[] value)=>Convert.ToBase64String(value).TrimEnd('=').Replace('+','-').Replace('/','_');var payload=JsonSerializer.SerializeToUtf8Bytes(claims,VaultSyncCrypto.Json);var receipt=new ErasureReceipt(kid,Encode(payload),Encode(key.SignData(payload,HashAlgorithmName.SHA256,DSASignatureFormat.IeeeP1363FixedFieldConcatenation)));var state=new AccountSyncState{Owner=owner,Subject=subject,Activated=true,AccessToken="synthetic-access",RefreshToken="synthetic-refresh"};new AccountSyncStore(root.FullName).Save(state);var spaces=new AccountWorkspaces(root.FullName);spaces.Remember(state);var foreign=spaces.Add("foreign@example.invalid");var foreignPath=spaces.DirectoryFor(foreign);new AccountSyncStore(foreignPath).Save(new(){Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262",Activated=true});spaces.Select(foreign);spaces.Remember(new AccountSyncStore(foreignPath).Load());spaces.Select(Guid.Empty);var foreignBytes=File.ReadAllBytes(Path.Combine(foreignPath,"account-sync.dpapi"));var hello=new WindowsHelloChallenge("UNSC-Relay-Vault-"+Guid.NewGuid().ToString("N"),"fixture",Convert.ToBase64String(publicKey));new WindowsHelloRegistration(root.FullName).RememberAuthenticated(hello,owner,subject);var vault=JsonSerializer.SerializeToUtf8Bytes(new{WindowsHello=new{Challenge=hello with{KeyName="UNSC-Relay-Vault-"+Guid.NewGuid().ToString("N")}},Ciphertext="fixture"});File.WriteAllBytes(Path.Combine(root.FullName,"keys.vault"),vault);File.WriteAllText(Path.Combine(root.FullName,"profiles.json"),"erased profiles");File.WriteAllText(Path.Combine(foreignPath,"profiles.json"),"foreign profiles");var backup=UpdateBackup.Create(root.FullName,"fixture");var migration=SyncLocalBackup.Create(root.FullName,true);var foreignMigration=Path.Combine(root.FullName,"MigrationBackups",DateTime.UtcNow.ToString("yyyyMMddTHHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(foreignMigration);new AccountSyncStore(foreignMigration).Save(new(){Owner=new string('B',64),Subject="62626262-6262-4262-8262-626262626262",Activated=true});File.WriteAllText(Path.Combine(foreignMigration,"keys.vault"),"foreign historical vault");var folder=Directory.CreateDirectory(Path.Combine(root.FullName,"Editor","nested"));File.WriteAllText(Path.Combine(folder.FullName,"secret.txt"),"temporary remote edit");var outside=Directory.CreateDirectory(Path.Combine(root.FullName,"external-export"));File.WriteAllText(Path.Combine(outside.FullName,"sentinel.txt"),"user-owned export");Directory.CreateSymbolicLink(Path.Combine(root.FullName,"NativeHome"),outside.FullName);File.WriteAllText(Path.Combine(root.FullName,"unrelated.txt"),"keep");var journal=new LocalErasureJournal(root.FullName,verifier);journal.Accept(receipt,owner,subject,claims.RequestId,Guid.Empty);var engine=new LocalAccountErasure(root.FullName,journal);var calls=0;
 using(var blocker=new FileStream(Path.Combine(root.FullName,"profiles.json"),FileMode.Open,FileAccess.Read,FileShare.Read)){try{await engine.Run(owner,_=>Task.CompletedTask);throw new Exception("Locked writer ignored");}catch(IOException){Check(!journal.Notices().Single().Completed&&File.Exists(Path.Combine(root.FullName,"account-sync.dpapi")),"busy files leave a durable pending journal and preserve identity for retry");}}
 var result=await engine.Run(owner,value=>{Check(value==hello,"Hello removal uses exact previously captured credential metadata");calls++;return Task.CompletedTask;});Check(result.Completed&&result.Files>0&&journal.Notices().Single().Completed,"completed state is persisted only after verified file and credential deletion");Check(!File.Exists(Path.Combine(root.FullName,"account-sync.dpapi"))&&!File.Exists(Path.Combine(backup,"account-sync.dpapi"))&&!File.Exists(Path.Combine(migration,"account-sync.dpapi")),"live, update and migration token copies are removed");Check(!File.Exists(Path.Combine(root.FullName,"keys.vault"))&&!Directory.Exists(Path.Combine(root.FullName,"Editor")),"vault and managed plaintext editor copies are removed including empty directory names");Check(File.ReadAllBytes(Path.Combine(foreignPath,"account-sync.dpapi")).SequenceEqual(foreignBytes)&&File.ReadAllText(Path.Combine(foreignPath,"profiles.json"))=="foreign profiles","another account remains byte-for-byte intact");Check(File.ReadAllText(Path.Combine(foreignMigration,"keys.vault"))=="foreign historical vault"&&new AccountSyncStore(foreignMigration).Load().Owner==new string('B',64),"foreign migration backup under a legacy root is independently attributed and preserved");Check(File.ReadAllText(Path.Combine(outside.FullName,"sentinel.txt"))=="user-owned export"&&!Directory.Exists(Path.Combine(root.FullName,"NativeHome")),"links are unlinked without touching external exports");Check(File.ReadAllText(Path.Combine(root.FullName,"unrelated.txt"))=="keep","unmanaged root files are preserved");Check(spaces.Load().Accounts.All(value=>value.Owner!=owner)&&new AccountWorkspaces(backup).Load().Accounts.All(value=>value.Owner!=owner),"shared live and backup indexes redact only the deleted owner");using(var manifest=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(backup,"manifest.json")))){var hashes=manifest.RootElement.GetProperty("hashes");Check(!hashes.TryGetProperty("account-sync.dpapi",out _)&&hashes.EnumerateObject().Any(value=>value.Name.Replace('\\','/')=="Accounts/"+foreign.ToString("N")+"/account-sync.dpapi"),"mixed backup manifests retain foreign account hashes while dropping erased credentials");}journal.GuardWorkspace(foreign);Check(true,"another account can open after cleanup");var again=await engine.Run(owner,_=>Task.CompletedTask);Check(again.Completed,"completed cleanup is safe to repeat after interruption or restore checks");
 // A restored signed-away account is blocked and erased again; a different subject is never inferred.
 new AccountSyncStore(root.FullName).Save(state);File.WriteAllBytes(Path.Combine(root.FullName,"keys.vault"),vault);try{journal.GuardWorkspace(Guid.Empty);throw new Exception("Restored account allowed");}catch(LocalAccountErasedException){Check(true,"permanent journal blocks resurrection after an old copy is restored");}await engine.Run(owner,_=>Task.CompletedTask);var interrupted=Path.Combine(root.FullName,"MigrationBackups",DateTime.UtcNow.ToString("yyyyMMddTHHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(interrupted);new AccountSyncStore(interrupted).Save(state);File.WriteAllText(Path.Combine(interrupted,"profiles.json"),"remaining migration after parent binding removal");await engine.Run(owner,_=>Task.CompletedTask);Check(!File.Exists(Path.Combine(interrupted,"account-sync.dpapi"))&&!File.Exists(Path.Combine(interrupted,"profiles.json")),"retry discovers independently bound migration copies even after the parent identity was removed");File.WriteAllText(Path.Combine(root.FullName,"profiles.json"),"unattributed residual");try{await engine.Run(owner,_=>Task.CompletedTask);throw new Exception("Unattributed data deleted");}catch(IOException){Check(File.Exists(Path.Combine(root.FullName,"profiles.json"))&&!journal.Notices().Single().Completed,"unattributed residuals stay untouched and never receive a false completed state");}Console.WriteLine("Local erasure engine checks: "+count);return 0;}finally{root.Delete(true);}}
}
